export interface VoiceMemberMoveEvent {
  guild_id: Snowflake;
  user_id: Snowflake;
  /**
   * The voice channel to move the member to, or null to disconnect them.
   */
  channel_id: Snowflake | null;
}
/**
 * etcd value at `/discordy/voice/nodes/<region>/<node_id>` (10 s lease, refreshed every 3 s).
 */
export interface VoiceNodeRegistration {
  node_id: string;
  region: string;
  ws_url: string;
  public_ip: string;
  udp_port: number;
  users: number;
  cpu_pct: number;
  egress_bps: number;
  draining: boolean;
  version: string;
}
/**
 * VOICE_QUALITY telemetry sample (discordy.telemetry.v1).
 */
export interface VoiceQualityEvent {
  source: "client" | "voice";
  user_id?: Snowflake;
  guild_id?: Snowflake | null;
  channel_id: Snowflake;
  node_id?: string;
  region?: string;
  jitter_ms: number;
  loss_pct: number;
  rtt_ms: number;
  bitrate_kbps: number;
}
/**
 * Voice op 2 READY.
 */
export interface VoiceReadyPayload {
  ssrc: number;
  ip: string;
  port: number;
  modes: "dtls-srtp"[];
  streams: VoiceStream[];
}
/**
 * A voice region.
 */
export interface VoiceRegion {
  id: string;
  name: string;
  optimal: boolean;
  deprecated?: boolean;
  custom?: boolean;
}
/**
 * VOICE_SERVER_UPDATE dispatch.
 */
export interface VoiceServerUpdateEvent {
  /**
   * Voice JWT (HS256, 60 s).
   */
  token: string;
  guild_id: Snowflake | null;
  channel_id: Snowflake;
  /**
   * Voice node WebSocket URL.
   */
  endpoint: string;
  region: string;
}
/**
 * Op 4 VOICE_STATE_UPDATE. guild_id is null for DM calls; channel_id null disconnects.
 */
export interface VoiceStateUpdatePayload {
  guild_id: Snowflake | null;
  channel_id: Snowflake | null;
  self_mute: boolean;
  self_deaf: boolean;
  self_video: boolean;
  self_stream: boolean;
}
/**
 * Op 23 VOICE_TELEMETRY.
 */
export interface VoiceTelemetryPayload {
  channel_id: Snowflake;
  jitter_ms: number;
  loss_pct: number;
  rtt_ms: number;
  bitrate_kbps: number;
}
/**
 * Claims of a voice JWT (HS256 with VOICE_TOKEN_SECRET, 60 seconds).
 */
export interface VoiceTokenClaims {
  sub: Snowflake;
  /**
   * Gateway session ID.
   */
  sid: string;
  srv: Snowflake;
  chn: Snowflake;
  /**
   * Allocated voice node ID.
   */
  node: string;
  e2ee: boolean;
  iat: number;
  exp: number;
}
/**
 * Op 24 WATCH_TOGETHER.
 */
export interface WatchTogetherPayload {
  channel_id: Snowflake;
  action: "load" | "play" | "pause" | "seek";
  url?: string;
  position_ms: number;
  /**
   * Server clock (unix ms) the position refers to.
   */
  at_server_ms: number;
}
